import * as React from "react";

export type SkateboardIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SkateboardIcon({ size = 20, ...props }: SkateboardIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M4 14.5h16"/><circle cx="8.5" cy="18.5" r="1.6"/><circle cx="15.5" cy="18.5" r="1.6"/>
    </svg>
  );
}
